function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,utarg,tstarg,nstarg)
[u] = ver_reg(ws,t_out,te,ks,ns,reg,est);
[uref] = ver_reg(utarg,t_out,tstarg,ks,nstarg,reg,est);
k1 = 0.053     ;
k2 = 0.128     ;
cb_in = 5      ;
Vo = 1         ;
lamb=1^-8      ;
cao=0.72       ;
cbo=0.05       ;
cd_mais = 0.15 ;
cb_mais = 0.025;

xtemp=x;
 u1 = myAD(u);
 x = myAD(x(1:n_s));
dx(1)=(-k1*x(1)*x(2)-( u(1)*x(3)^(-1) )*x(1)                           )*tal;
dx(2)=(-k1*x(1)*x(2) - 2*k2*x(2)^2 + ( (u(1)*x(3)^(-1))*(cb_in - x(2))))*tal;
dx(3)=(u(1)                                                       )*tal;
dx0 = getvalue(dx);
dx1 = getderivs(dx);
dx=[];
x=[];
x = xtemp;
u = u1;
dz(1)=(-k1*x(1)*x(2)-( u(1)*x(3)^(-1) )*x(1)                           )*tal;
dz(2)=(-k1*x(1)*x(2) - 2*k2*x(2)^2 + ( (u(1)*x(3)^(-1))*(cb_in - x(2))))*tal;
dz(3)=(u(1)                                                       )*tal;

dx2 = getderivs(dz);

j1 = [dx1 dx2];
% dx = [dx1 ; dx2];
%  dx=transp(dx1);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
